import {mountCropTiles} from './crop-tiles.mjs?v=crop-tiles-v5';
import {mountDurian} from './durian-guide.mjs?v=crop-tiles-v5';
const text={
 en:{title:'Guide my crop',intro:'Choose your crop, goal and visible growth. Get your next three steps.',labels:['Crop','My goal','What I can see','Recent nitrogen fertilizer','Water / weather','Crop maturity'],goals:['Establish / grow','Prepare for flowering','Support fruit development','Recover after harvest'],signs:['Choose an observation','Soft new leaves / shoots extending','Leaves fully expanded and firm; growth slowing','Flower buds or flowers visible','Fruit developing','Yellowing, wilting or declining growth','Not sure'],nitrogen:['Not sure','Applied recently','No recent application'],water:['Not sure','Dry soil / prolonged dry weather','Wet soil / standing water','No obvious water stress'],age:['Not sure','Young / not yet bearing','Has flowered or fruited before'],submit:'Show my next steps',stage:'What your observations suggest',cn:'How C:N helps explain this',next:'Your next three steps',watch:'What to watch / when to check',crop:'Crop-specific check',basis:'Basis and limits',choose:'Choose what you can see first.',evidence:'A guide based on your selections and published plant physiology; not a measured C:N result or an AI diagnosis.',go:'Explore the crop evidence',back:'Learn the principles',need:'For a flowering decision, also record variety, location, last flush date and local flowering season.',young:'A young crop may not be reproductively mature. Confirm the expected bearing age for your variety before seeking induction.',n:'Record the product, nitrogen percentage, amount and application date before deciding on another application.',wet:'Check drainage and standing water first; impaired roots can limit nutrient uptake.',dry:'Check soil moisture in the root zone and irrigation delivery before treating poor growth as a nutrient problem.',unknown:'Record the last fertilizer date and check root-zone moisture; complete whichever is still unknown in this assessment.',stageNames:['','Active vegetative growth','Maturing leaves / shoots','Reproductive development','Fruit development','Stress needs investigation','Stage not established'],explain:['','Expanding shoots use carbon compounds and nitrogen to build tissue. Vigorous growth alone does not establish low C:N.','Slower extension and firm, expanded leaves indicate maturation. This may accompany changing carbon and nitrogen allocation; it does not prove rising C:N or flower readiness.','Visible flowers establish reproductive development. C:N is part of resource allocation, rather than a universal flowering switch.','Leaves supply carbon compounds to developing fruit; nitrogen also supports plant functions. A higher ratio alone is not the goal.','Stress may reduce photosynthesis or nutrient uptake. Yellow leaves do not demonstrate useful high C:N.','Identify the growth stage before drawing a C:N conclusion.'],actions:['','Mark representative shoots and photograph them weekly.|Review recent nitrogen and irrigation records alongside the new growth.|For flowering, first check shoot maturity and the crop-specific seasonal conditions.','Record the date growth slowed and whether leaves are firm and fully expanded.|Check variety, crop maturity and local temperature / seasonal requirements.|Keep tracking buds; do not choose a flowering treatment from leaf appearance alone.','Distinguish visible flower buds, open flowers and fruit set in your record.|Check crop-specific water and nutrition needs for this reproductive stage.|Record flower loss or poor set separately; check the crop evidence for pollination and weather factors.','Record fruit set date, fruit load and current leaf condition.|Check irrigation delivery and whether healthy leaves remain available to supply fruit.|Use crop-specific nutrition guidance and appropriate tissue sampling before changing nutrient rates.','Check root-zone moisture, drainage and visible pest or disease damage.|Record whether symptoms affect old leaves, new leaves or whole branches.|If decline persists or spreads, take photos and a representative sample to local extension before changing fertilizer.','Photograph the whole plant plus a shoot tip and old / young leaves.|Record whether new leaves are expanding, firm, flowering or carrying fruit.|Compare these observations with the growth stages, then run the guide again.'],review:['','Compare the same shoots weekly for firmer leaves and slower extension.','Look weekly for bud changes. Maturity is a checkpoint, not a promised flowering date.','Observe flowers and fruit set through the crop’s flowering period.','Track fruit development and leaf condition weekly; investigate sudden drop promptly.','Recheck promptly after the moisture / drainage check; seek local help if symptoms worsen.','Reassess after you can identify one visible stage.'],recover:'After harvest, record remaining leaf health and the next flush. Recovery concerns both carbon supply and nutrient replacement; do not force a high ratio.',goalLabel:'Your goal'},
 zh:{title:'指导我的作物',intro:'选作物、目标和眼前的生长情况，得到接下来三步。',labels:['作物','我的目标','我看见的情况','近期施氮肥','水分 / 天气','作物成熟程度'],goals:['建株 / 长树','准备开花','支持果实发育','采后恢复'],signs:['先选一种观察','新叶柔软 / 新梢正在伸长','叶片展开变硬，生长放慢','看见花芽或花','果实正在发育','黄叶、萎蔫或生长衰退','不确定'],nitrogen:['不确定','近期施过','近期没施'],water:['不确定','土壤偏干 / 持续干旱','土壤积水 / 长期湿润','没有明显水分胁迫'],age:['不确定','幼株 / 尚未结果','曾经开花或结果'],submit:'看接下来怎么做',stage:'观察提示的阶段',cn:'C:N 怎样帮助理解',next:'接下来三步',watch:'看什么变化 / 何时再检查',crop:'这种作物先核对什么',basis:'依据与边界',choose:'请先选择眼前看见的情况。',evidence:'根据你的选择与公开植物生理资料整理；不是实测 C:N，也不是 AI 诊断。',go:'查看这项作物的证据',back:'学习原理',need:'要判断花前准备，还需记录品种、地点、末次抽梢日期和本地花期。',young:'幼株可能尚未达到生殖成熟。先核对该品种通常的结果年龄，再考虑诱导。',n:'先记录产品、含氮百分比、用量和日期，再决定是否追加。',wet:'先检查排水与积水；根系受影响也会限制养分吸收。',dry:'先检查根区土壤湿度和灌溉是否到位，再把弱长归因于养分。',unknown:'补齐尚不清楚的背景：末次施肥日期或根区水分。',stageNames:['','营养生长活跃','叶片 / 枝梢成熟中','生殖发育','果实发育','优先查明胁迫','阶段尚未确定'],explain:['','新梢需要碳化合物和氮来建造组织。旺长本身不能证明 C:N 低。','伸长放慢、叶片展开变硬提示成熟。碳氮分配可能同时改变，但这不能证明 C:N 升高或已准备好开花。','看见花说明已进入生殖发育。C:N 参与资源分配，不是通用的开花开关。','叶片向果实供应碳化合物，氮也支持植物运作。目标不是单纯提高比例。','胁迫可能降低光合或养分吸收。黄叶不代表有益的高 C:N。','先确定生长阶段，再讨论 C:N。'],actions:['','标记有代表性的枝梢，每周拍同一位置。|把近期施氮、灌溉记录与抽梢情况对照。|若想开花，先核对梢熟及该作物所需的季节条件。','记录伸长放慢的日期及叶片是否展开变硬。|核对品种、作物成熟程度及当地温度 / 季节要求。|继续观察芽的变化，不凭叶片外观选择催花处理。','分开记录可见花芽、开花和坐果。|核对该作物生殖阶段的供水及营养需求。|单独记录落花或坐果差，再查该作物的授粉与天气因素。','记录坐果日期、挂果量和叶片状态。|检查灌溉是否到位，是否保有健康叶片供应果实。|改变养分用量前，先参考作物专属指导及适当的组织取样。','检查根区水分、排水和可见病虫损伤。|记录症状发生在老叶、新叶还是整条枝。|若衰退持续或扩散，带照片和代表性样本咨询当地农技人员，再调整肥料。','拍整株、梢端以及新老叶。|记录新叶是在展开、变硬，还是已开花挂果。|对照生长阶段后再运行指导。'],review:['','每周对照同一枝梢，观察叶片变硬及伸长放慢。','每周看芽的变化。成熟是检查点，不是保证开花的日期。','在该作物的花期持续观察花与坐果。','每周记录果实和叶片；突然落果应及时排查。','检查水分与排水后及时复查；症状加重就寻求当地帮助。','能辨认一种生长情况后再判断。'],recover:'采后先记录剩余叶片健康和下一轮抽梢。恢复涉及碳供应与养分补充，不是强求高比例。',goalLabel:'你的目标'},
 ms:{title:'Panduan tanaman saya',intro:'Pilih tanaman, matlamat dan pertumbuhan yang dilihat untuk mendapat tiga langkah seterusnya.',labels:['Tanaman','Matlamat saya','Apa yang saya lihat','Baja nitrogen terkini','Air / cuaca','Kematangan tanaman'],goals:['Pembentukan / pertumbuhan','Persediaan pembungaan','Sokong perkembangan buah','Pemulihan selepas tuaian'],signs:['Pilih pemerhatian dahulu','Daun lembut / pucuk memanjang','Daun berkembang penuh dan keras; pertumbuhan perlahan','Putik bunga atau bunga kelihatan','Buah sedang berkembang','Daun kuning, layu atau pertumbuhan merosot','Tidak pasti'],nitrogen:['Tidak pasti','Baru digunakan','Tiada penggunaan terkini'],water:['Tidak pasti','Tanah kering / cuaca kering berpanjangan','Tanah basah / air bertakung','Tiada tekanan air yang jelas'],age:['Tidak pasti','Muda / belum berbuah','Pernah berbunga atau berbuah'],submit:'Lihat langkah seterusnya',stage:'Peringkat berdasarkan pemerhatian',cn:'Bagaimana C:N membantu pemahaman',next:'Tiga langkah seterusnya',watch:'Apa dipantau / bila diperiksa',crop:'Semakan khusus tanaman',basis:'Asas dan batasan',choose:'Pilih pemerhatian terlebih dahulu.',evidence:'Panduan berdasarkan pilihan anda dan fisiologi tumbuhan yang diterbitkan; bukan ukuran C:N atau diagnosis AI.',go:'Lihat bukti tanaman ini',back:'Pelajari prinsip',need:'Untuk keputusan pembungaan, catat juga varieti, lokasi, tarikh pucuk terakhir dan musim berbunga tempatan.',young:'Tanaman muda mungkin belum matang untuk pembiakan. Semak umur mula berbuah bagi varieti sebelum mempertimbangkan aruhan.',n:'Catat produk, peratus nitrogen, kuantiti dan tarikh sebelum memutuskan penggunaan tambahan.',wet:'Periksa saliran dan air bertakung dahulu; akar terjejas boleh mengehadkan pengambilan nutrien.',dry:'Periksa kelembapan zon akar dan bekalan pengairan sebelum menganggap pertumbuhan lemah sebagai masalah nutrien.',unknown:'Lengkapkan maklumat yang belum diketahui: tarikh baja terakhir atau kelembapan zon akar.',stageNames:['','Pertumbuhan vegetatif aktif','Pematangan daun / pucuk','Perkembangan pembiakan','Perkembangan buah','Siasat tekanan dahulu','Peringkat belum dikenal pasti'],explain:['','Pucuk yang berkembang menggunakan sebatian karbon dan nitrogen untuk membina tisu. Pertumbuhan subur sahaja tidak membuktikan C:N rendah.','Pemanjangan perlahan dan daun keras yang berkembang penuh menunjukkan pematangan. Pengagihan karbon dan nitrogen mungkin berubah, tetapi ini tidak membuktikan C:N meningkat atau kesediaan berbunga.','Bunga yang kelihatan menunjukkan perkembangan pembiakan. C:N berkaitan pengagihan sumber, bukan suis pembungaan sejagat.','Daun membekalkan sebatian karbon kepada buah; nitrogen juga menyokong fungsi tumbuhan. Nisbah lebih tinggi sahaja bukan matlamat.','Tekanan boleh mengurangkan fotosintesis atau pengambilan nutrien. Daun kuning bukan bukti C:N tinggi yang bermanfaat.','Kenal pasti peringkat pertumbuhan sebelum membuat kesimpulan tentang C:N.'],actions:['','Tandakan pucuk yang mewakili tanaman dan ambil foto setiap minggu.|Semak rekod nitrogen dan pengairan bersama pertumbuhan baharu.|Untuk pembungaan, semak kematangan pucuk dan keadaan musim khusus tanaman dahulu.','Catat tarikh pertumbuhan perlahan dan sama ada daun keras serta berkembang penuh.|Semak varieti, kematangan tanaman dan keperluan suhu / musim tempatan.|Pantau perubahan tunas; jangan pilih rawatan pembungaan berdasarkan rupa daun sahaja.','Bezakan putik bunga, bunga terbuka dan pembentukan buah dalam rekod.|Semak keperluan air dan nutrisi tanaman bagi peringkat ini.|Catat keguguran bunga atau pembentukan buah lemah secara berasingan; semak pendebungaan dan cuaca.','Catat tarikh pembentukan buah, beban buah dan keadaan daun.|Periksa pengairan dan kewujudan daun sihat untuk membekalkan buah.|Rujuk nutrisi khusus tanaman dan persampelan tisu sesuai sebelum menukar kadar nutrien.','Periksa kelembapan zon akar, saliran serta kerosakan perosak atau penyakit.|Catat sama ada gejala pada daun tua, daun muda atau seluruh dahan.|Jika kemerosotan berterusan atau merebak, bawa foto dan sampel kepada pegawai pertanian sebelum menukar baja.','Ambil foto seluruh tanaman, hujung pucuk serta daun tua dan muda.|Catat sama ada daun sedang berkembang, mengeras, berbunga atau berbuah.|Bandingkan dengan peringkat pertumbuhan, kemudian gunakan panduan semula.'],review:['','Bandingkan pucuk sama setiap minggu untuk daun lebih keras dan pemanjangan perlahan.','Pantau tunas setiap minggu. Kematangan ialah titik semakan, bukan tarikh jaminan bunga.','Pantau bunga dan pembentukan buah sepanjang musim berbunga tanaman.','Pantau buah dan daun setiap minggu; siasat keguguran mendadak segera.','Periksa semula segera selepas semakan air / saliran; dapatkan bantuan jika gejala bertambah teruk.','Nilai semula selepas satu peringkat dapat dikenal pasti.'],recover:'Selepas tuaian, catat kesihatan daun dan pucuk seterusnya. Pemulihan melibatkan bekalan karbon dan penggantian nutrien, bukan memaksa nisbah tinggi.',goalLabel:'Matlamat anda'}
};
const priorities={
 en:['Support establishment and healthy leaf growth; check water and nutrient supply before changing fertilizer.','Compare the current flush with your last successful flowering record; without one, obtain local variety guidance before choosing an induction treatment.','Confirm whether fruit has set; if it has, prioritise fruit load, healthy leaves and irrigation.','Check remaining leaf health and the next flush before planning nutrient replacement.'],
 zh:['先支持建株与健康叶片，改变肥料前核对水分及养分供应。','把本轮抽梢与上次成功开花的记录对照；没有记录时，先取得本地品种指导，再选择诱导处理。','先确认是否坐果；已坐果则优先检查挂果量、健康叶片及灌溉。','安排养分补充前，先检查采后剩余叶片健康和下一轮抽梢。'],
 ms:['Sokong pembentukan dan daun sihat; semak air dan nutrien sebelum menukar baja.','Bandingkan pucuk semasa dengan rekod pembungaan berjaya dahulu; jika tiada, dapatkan panduan varieti tempatan sebelum memilih rawatan aruhan.','Sahkan pembentukan buah dahulu; jika sudah berbuah, utamakan beban buah, daun sihat dan pengairan.','Periksa kesihatan daun selepas tuaian dan pucuk seterusnya sebelum merancang penggantian nutrien.']
};
export function assessGuide({sign,water,age,goal}){const stage=Number(sign);return {stage,stress:stage===5,young:age==='1'&&goal==='1',waterCheck:water==='1'?'dry':water==='2'?'wet':null};}
export function mountGuide({language,crops,refs,esc,onCrop,sources}){
 const t=text[language]||text.en,root=document.getElementById('crop-guide');
 const options=a=>a.map((v,i)=>`<option value="${i}">${esc(v)}</option>`).join('');
 root.innerHTML=`<h1>${t.title}</h1><p>${t.intro}</p><form id="guide-form"><div class="guide-fields"><label>${t.labels[0]}<select id="guide-crop">${Object.entries(crops).map(([id,c])=>`<option value="${id}">${esc(c.name)}</option>`).join('')}</select></label>${[['goal',t.goals],['sign',t.signs],['nitrogen',t.nitrogen],['water',t.water],['age',t.age]].map(([id,a],i)=>`<label>${t.labels[i+1]}<select id="guide-${id}">${options(a)}</select></label>`).join('')}</div><button class="primary" type="submit">${t.submit}</button><p id="guide-error" role="alert"></p></form><div id="guide-result" aria-live="polite"></div>`;
 const form=document.getElementById('guide-form'),result=document.getElementById('guide-result');
 try{const saved=JSON.parse(localStorage.getItem('cn-guide-v1')||'{}');for(const [key,value] of Object.entries(saved)){const el=document.getElementById('guide-'+key);if(el&&[...el.options].some(o=>o.value===value))el.value=value;}}catch{}
 const save=()=>{try{localStorage.setItem('cn-guide-v1',JSON.stringify(Object.fromEntries(['crop','goal','sign','nitrogen','water','age'].map(key=>[key,document.getElementById('guide-'+key).value]))));}catch{}};
 form.addEventListener('change',save);
 const requestedCrop=new URLSearchParams(location.search).get('crop');if(crops[requestedCrop])document.getElementById('guide-crop').value=requestedCrop;
 mountCropTiles({select:document.getElementById('guide-crop'),crops,language,esc});
 const durianRoot=document.createElement('div');durianRoot.id='durian-workflow';form.after(durianRoot);
 const syncCrop=()=>{const isDurian=document.getElementById('guide-crop').value==='durian';root.children[0].hidden=isDurian;root.children[1].hidden=isDurian;[...form.querySelectorAll('.guide-fields label')].slice(1).forEach(el=>el.hidden=isDurian);form.querySelector('button[type="submit"]').hidden=isDurian;document.getElementById('guide-error').hidden=isDurian;durianRoot.hidden=!isDurian;result.hidden=isDurian;if(isDurian)mountDurian({root:durianRoot,language,esc,sources});};
 syncCrop();document.getElementById('guide-crop').addEventListener('change',()=>{const url=new URL(location.href);url.searchParams.set('crop',document.getElementById('guide-crop').value);history.replaceState(null,'',url);syncCrop();});
 const clear=()=>{result.replaceChildren();};form.addEventListener('change',clear);
 form.onsubmit=e=>{e.preventDefault();const val=id=>document.getElementById('guide-'+id).value;const input=Object.fromEntries(['crop','goal','sign','nitrogen','water','age'].map(id=>[id,val(id)]));const a=assessGuide(input),c=crops[input.crop];document.getElementById('guide-error').textContent=a.stage===0?t.choose:'';if(!a.stage)return;
 const steps=t.actions[a.stage].split('|');if(a.stage!==5&&a.stage!==6)steps[2]=priorities[language][input.goal];
 const context=[a.waterCheck?t[a.waterCheck]:null,input.nitrogen==='1'?t.n:null,input.nitrogen==='0'||input.water==='0'?t.unknown:null,a.young?t.young:null].filter(Boolean);
 result.innerHTML=`<article class="card guide-conclusion"><span class="pill">${esc(c.name)} · ${t.goals[input.goal]}</span><h2>${t.stage}: ${t.stageNames[a.stage]}</h2><h3>${t.cn}</h3><p>${t.explain[a.stage]}</p>${input.goal==='3'?`<p>${t.recover}</p>`:''}<h3>${t.next}</h3><ol>${steps.map(v=>`<li>${v}</li>`).join('')}</ol>${context.length?`<div class="callout">${context.map(v=>`<p>${v}</p>`).join('')}</div>`:''}<h3>${t.watch}</h3><p>${t.review[a.stage]}</p>${input.goal==='1'?`<p>${t.need}</p>`:''}<h3>${t.crop}</h3><p>${esc(c.factors[0][1])}</p><button type="button" id="guide-crop-evidence" class="secondary">${t.go}</button><details><summary>${t.basis}</summary><p>${t.evidence}</p>${refs([...new Set(['E1','E2',...c.refs])])}</details></article>`;
 document.getElementById('guide-crop-evidence').onclick=()=>onCrop(input.crop);result.scrollIntoView({behavior:'smooth',block:'start'});
 };
 return t.title;
}
